# four_numbers: given a list of up to four distinct integers between 1 and 10,
# find three integers (also between 1 and 10) such that all the original numbers
# can be generated by summing subsets of these three numbers. Output x: the three integers.
import itertools

import cvc5.pythonic as cz


def build(instance):
    numbers = instance["numbers"]
    x = [cz.Int("x0"), cz.Int("x1"), cz.Int("x2")]

    constraints = []

    # Print the list of three integers (x) between 1 and 10, inclusive.
    for xi in x:
        constraints.append(xi >= 1)
        constraints.append(xi <= 10)

    # all the original numbers can be generated by summing subsets of these three numbers
    # (every subset of x sums to a value; each input number must equal one such sum)
    subsets = []
    for size in range(1, 4):
        for idx in itertools.combinations(range(3), size):
            expr = x[idx[0]]
            for j in idx[1:]:
                expr = expr + x[j]
            subsets.append(expr)

    for v in numbers:
        constraints.append(cz.Or([s == v for s in subsets]))

    return constraints, {"x": x}
